head.script:
scwin.screenId = "jldbnf25700";

///////// 1. 변수 및 선언 영역 /////////

scwin.rownum = 0;

scwin.chgSeq = 900;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb4", fn: function () { return String(dma_bndInfo.get("isuAmt")) + " 원"; } },
        { childId: "__rb6", fn: function () { return String(dma_bndInfo.get("listAmt")) + " 원"; } },
        { childId: "__rb7", fn: function () { return String(dma_bndInfo.get("bfchgCoupnRt")) + " %"; } },
        { childId: "__rb13", fn: function () { return String(dma_bndInfo.get("spdSgn")) + " " + String(dma_bndInfo.get("spd")) + "%"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.getBdchrgInfo($c.util.getComponent('slc_bdchrgTpCd'));
        clickedRow = null;
        $("#tbl_schdl").on("click", "tr", function() {
                clickedRow = $(this);
                $("tr").removeClass("on");
                $(this).addClass("on");
                const frnids_chg_tp_cd = $(this).find("input[name='frnids_chg_tp_cd']").val();
                if (frnids_chg_tp_cd === "D") {
                    $c.util.getComponent('txt_delRow').setLabel("삭제취소");
                } else {
                    $c.util.getComponent('txt_delRow').setLabel("일정삭제");
                }
        });
        $("#txt_addRow").click(async function() {
                if (clickedRow) {
                    const can_add_row = clickedRow.find("input[name='canAddRow']").val();
                    if (can_add_row != null && can_add_row === "N") {
                        await $c.win.alert("신고완료된 일정 중간에는 행추가 할 수 없습니다.");
                        return;
                    }
                    scwin.addSchdl(clickedRow);
                } else {
                    await $c.win.alert("행추가할 위치를 선택하세요.\n선택 된 행의 아래에 새로운 행이 추가됩니다.");
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Apply();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf25700.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_mpd_files_select_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files')); 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_mpd_files_select_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_mpd_files_del_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); } 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_mpd_files_del_onclick' }); }
};

