        /* sdd-asis-lifecycle:begin btn_DelSchdl1_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.delSchdl1()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_DelSchdl1_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_bdchrgTpCd_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_bdchrgTpCd_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_bdchrgTpCd_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.getBdchrgInfo(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.slc_bdchrgTpCd_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_fileBrowse_onclick
 * @author Inswave
 * @date 2026. 09. 29
