        /* sdd-asis-lifecycle:begin btn_Apply_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.apply()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf25700.btn_Apply_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_goToList_onclick
 * @author Inswave
 * @date 2026. 09. 29
