/**
 * @method
 * @name scwin.addSchdl
 * @author Inswave
 * @date 2026. 09. 29
 * @param clickedRow
 * @returns
 * @hidden N
*/
scwin.addSchdl = function (clickedRow) {
    /* sdd-asis-lifecycle:begin fn_AddSchdl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const $tblSchdl = $('#tbl_schdl');
    const $tr = $("<tr></tr>");
    const $td1 = $("<td><input type='checkbox' name='chks' /></td>").addClass('first txc');
    const $td2 = $("<td><input type='hidden' name='intRtChgSeq' value='" + scwin.chgSeq + "'></td>");
    const $td3 = $("<td><input type='hidden' name='bfchg_int_fix_dd' value=''></td>");
    const $td4 = $("<td><div style='display:flex; align-items:center; justify-content: center;'><input type='text' name='afchg_int_fix_dd' value='' class='txt input-calendar' title='날짜입력' onBlur=\"Chk_Date2( this,'결정기준일' )\" onfocus=\"cal_offMask('document.SendForm.afchg_int_fix_dd')\" onkeyup='chkDate2(this)' /></div></td>").addClass('txc');
    const $td5 = $("<td><input type='hidden' name='bfchg_int_pay_dd' value=''></td>");
    const $td6 = $("<td><div style='display:flex; align-items:center; justify-content: center;'><input type='text' name='afchg_int_pay_dd' value='' class='txt input-calendar' title='날짜입력' onBlur=\"Chk_Date2( this,'이자지급일' )\" onfocus=\"cal_offMask('document.SendForm.afchg_int_pay_dd')\" onkeyup='chkDate2(this)' /></div></td>").addClass('txc');
    const $td7 = $("<td><input type='hidden' name='frnids_chg_tp_cd' value='N'></td>").addClass('last');
    scwin.chgSeq++;
    $tr.append($td1);
    $tr.append($td2);
    $tr.append($td3);
    $tr.append($td4);
    $tr.append($td5);
    $tr.append($td6);
    $tr.append($td7);
    clickedRow.after($tr);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delSchdl
 * @author Inswave
 * @date 2026. 09. 29
 * @param clickedRow
 * @returns
 * @hidden N
*/
scwin.delSchdl = async function (clickedRow) {
    /* sdd-asis-lifecycle:begin fn_DelSchdl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let chk_num = 0;
    for (let r = 0, n = $c.util.getComponent('dlt_schdlList').getTotalRow(); r < n; r++) {/* 수동 전환 필요: DOM 관용구 $(this) 잔존 — 행 순회 안에서 해석 못 함(D19-b) */
        if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_schdlList').getCellData(r, 'chks'))) >= 0)) {
            chk_num++;
            const frnids_chg_tp_cd = $(this).closest('tr').find("input[name='frnids_chg_tp_cd']").val();
            if (frnids_chg_tp_cd === "M") {
                const seq = $(this).closest('tr').find("input[name='intRtChgSeq']").val();
                const bfchg_int_fix_dd = $(this).closest('tr').find("input[name='bfchg_int_fix_dd']").val();
                const bfchg_int_pay_dd = $(this).closest('tr').find("input[name='bfchg_int_pay_dd']").val();
                scwin.putDeleteSeq(seq, bfchg_int_fix_dd, bfchg_int_pay_dd);
            }
            $(this).closest('tr').remove();
        }
    }
    if (chk_num == 0) {
        await $c.win.alert("삭제할 행을 체크하세요.");
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delSchdl1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.delSchdl1 = async function () {
    /* sdd-asis-lifecycle:begin fn_DelSchdl1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (clickedRow == null || clickedRow == null) {
        return;
    }
    const isChecked = clickedRow.find("input[name='chks']").is(":checked");
    if (isChecked) {
        const frnids_chg_tp_cd = clickedRow.find("input[name='frnids_chg_tp_cd']").val();
        if (frnids_chg_tp_cd === "N") {
            clickedRow.remove();
        } else {
            if (frnids_chg_tp_cd === "M") {
                clickedRow.find("input[name='frnids_chg_tp_cd']").val("D");
                clickedRow.addClass('strikethrough');
                $c.util.getComponent('txt_delRow').setLabel("삭제취소");
            } else {
                if (frnids_chg_tp_cd === "D") {
                    clickedRow.find("input[name='frnids_chg_tp_cd']").val("M");
                    clickedRow.find("input[name='chks']").prop("checked", false);
                    clickedRow.removeClass('strikethrough');
                    $c.util.getComponent('txt_delRow').setLabel("일정삭제");
                }
            }
        }
    } else {
        await $c.win.alert("삭제할 행을 체크하세요.");
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.putDeleteSeq
 * @author Inswave
 * @date 2026. 09. 29
 * @param seq int_fix_dd int_pay_dd
 * @returns
 * @hidden N
*/
scwin.putDeleteSeq = function (seq, int_fix_dd, int_pay_dd) {
    /* sdd-asis-lifecycle:begin fn_PutDeleteSeq — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (seq != null && seq !== "") {
        const newInput1 = $('<input>', { type: 'text', name: 'del_int_rt_seq', value: seq });
        const newInput2 = $('<input>', { type: 'text', name: 'del_int_fix_dd', value: int_fix_dd });
        const newInput3 = $('<input>', { type: 'text', name: 'del_int_pay_dd', value: int_pay_dd });
        $("#delSeq").append(newInput1);
        $("#delSeq").append(newInput2);
        $("#delSeq").append(newInput3);
    }
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.getBdchrgInfoDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.getBdchrgInfoDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_GetBdchrgInfo_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_chrgId').setValue(result.chrg_id);
    $c.util.getComponent('ipt_chrgNm').setValue(result.chrg_nm);
    $c.util.getComponent('ipt_jobposNm').setValue(result.jobpos_nm);
    $c.util.getComponent('ipt_belngInstNm').setValue(result.belng_inst_nm);
    $c.util.getComponent('ipt_belngDepNm').setValue(result.belng_dep_nm);
    scwin.setTelNo(result.tel_no);
    scwin.setCellphoneNo(result.cellphone_no);
    scwin.setEmail(result.email);
    scwin.setFaxNo(result.fax_no);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.getBdchrgInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getBdchrgInfo = async function () {
    const r = await scwin.tx_fn_GetBdchrgInfo();
    try {
        scwin.getBdchrgInfoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf25700.fn_GetBdchrgInfo' });
    }
    return r;
};
